-- Property Maintenance Operative (ST0171 v1.1) in Evia Portal: the course, its standard (every KSB word for word, as in
-- Evia) and its course pack (the 10 units and their KSBs), so colleges can enrol learners on it and Milos, Paros and
-- Symi follow the same units. Adds rows only; changes nothing that exists. Safe to run again.
insert into public.courses (code, title, source_system, is_published, published_at)
select 'pmo', 'Property Maintenance Operative (ST0171)', 'evia', true, now()
where not exists (select 1 from public.courses where code = 'pmo');
do $seed$ declare v uuid; begin
  if not exists (select 1 from public.qualification_versions v join public.qualifications q on q.id = v.qualification_id where q.code = 'ST0171' and v.version = '1.1') then
    v := private.save_standard($std${"code":"ST0171","kind":"standard","title":"Property maintenance operative","level":2,"version":"1.1","source_note":"Apprenticeship standard ST0171 v1.1. KSBs word for word, as in Evia.","requirements":[{"code":"K1","kind":"knowledge","title":"The principles and requirements of planned preventative maintenance (PPM) and reactive maintenance."},{"code":"K2","kind":"knowledge","title":"The range of building types and characteristic uses, their common methods of construction and typical defects, and the impact that property maintenance operations may have on building safety."},{"code":"K3","kind":"knowledge","title":"Health and safety regulations, relevance to the occupation and the operative's responsibilities. Health and Safety at Work Act Control of Substances Hazardous to Health (COSHH). Manual handling. Personal Protective Equipment (PPE). Working at height. Safety equipment: guards, signage, fire extinguishers."},{"code":"K4","kind":"knowledge","title":"Risks and hazards associated with property maintenance activities, and their mitigation using risk assessment."},{"code":"K5","kind":"knowledge","title":"Key regulatory and legislative requirements (including building regulations, the building safety bill, and BSI Flex 8670), and an awareness of how these apply to varying property types, and their impact on property maintenance operatives’ responsibilities."},{"code":"K6","kind":"knowledge","title":"Importance of establishing a safe and tidy work area, using appropriate access equipment, providing protection to adjacent areas, and consideration for the safety of other property users."},{"code":"K7","kind":"knowledge","title":"Common hand and power tools and equipment used in routine property maintenance tasks and how to use safely."},{"code":"K8","kind":"knowledge","title":"The common components of electrical and electronic systems, how to safely isolate electrical supplies and the procedures for correctly reporting identified faults."},{"code":"K9","kind":"knowledge","title":"The common forms of emergency equipment and signage, their importance within buildings and the preventative and possible corrective maintenance required."},{"code":"K10","kind":"knowledge","title":"The principles and components of plumbing systems, how to safely isolate, store and drain down water supplies to diagnose faults and clear blockages."},{"code":"K11","kind":"knowledge","title":"The principles and components of common above and below ground drainage systems, the issues that poor drainage can have on properties and how to diagnose faults and clear blockages."},{"code":"K12","kind":"knowledge","title":"The principles of good water hygiene to preserve and maintain the health of water systems within buildings and how these are checked and legally certified to minimise water hygiene and legionella risks."},{"code":"K13","kind":"knowledge","title":"The principles and components of common environmental and energy management systems and their methods of operation."},{"code":"K14","kind":"knowledge","title":"The common defects found in windows, doors, and glazing systems, the characteristics, uses and limitations of the materials and components used within them, and how these are used to meet statutory regulations."},{"code":"K15","kind":"knowledge","title":"The common types of materials and processes used to prepare, repair and finish plaster defects."},{"code":"K16","kind":"knowledge","title":"The common causes of painting and decorating defects, and the types of materials, chemicals and processes used in painting and decorating activities. How paints and chemicals are stored and disposed of safely."},{"code":"K17","kind":"knowledge","title":"The common causes of tiling defects and the types of materials and processes used in tiling activities."},{"code":"K18","kind":"knowledge","title":"The common causes of flooring defects and the types of materials and processes used in flooring repairs."},{"code":"K19","kind":"knowledge","title":"The common forms of masonry and damp proofing defects, materials and processes used in masonry repair activities: Mixing mortars, replacing defective pointing, laying and bonding of masonry, coping repairs and damp-proofing."},{"code":"K20","kind":"knowledge","title":"The common types of roof structures, defects and the types of materials and processes used in remedial and temporary repair."},{"code":"K21","kind":"knowledge","title":"The common types of fencing and railing systems, their typical defects, and the types of materials and processes used in repairs."},{"code":"K22","kind":"knowledge","title":"The common types of groundwork and landscaping systems, their typical defects and the types of materials and processes used in remedial repair."},{"code":"K23","kind":"knowledge","title":"Technical sources of information and data used in property maintenance operations."},{"code":"K24","kind":"knowledge","title":"The methods to record information and data via written and digital means and the importance of data protection and security."},{"code":"K25","kind":"knowledge","title":"The purpose of quality assurance and continuous improvement and how these improve commonly occurring faults or inefficiencies."},{"code":"K26","kind":"knowledge","title":"Environmental regulations and requirements: Environmental Protection Act, safe disposal of waste, minimising waste (re-use and re-cycle), waste contractors permit, energy efficiency, and contribution to net zero outcomes."},{"code":"K27","kind":"knowledge","title":"Methods of communication and when to use industry terminology to match the style to the audience."},{"code":"K28","kind":"knowledge","title":"The importance of customer service to their organisation, how to provide feedback to ensure customers are informed of property maintenance."},{"code":"K29","kind":"knowledge","title":"The roles and responsibilities of property maintenance operatives and the purpose and inter-dependencies of other trade operatives."},{"code":"K30","kind":"knowledge","title":"The rights and responsibilities of an employee and employer and an awareness of equality, diversity and inclusion, safeguarding and prevent."},{"code":"K31","kind":"knowledge","title":"The purpose of continuing professional development (CPD) and how this supports them to understand their limits for personal authority and competence."},{"code":"S1","kind":"skill","title":"Plan the sequence of work required to carry out routine property maintenance operations."},{"code":"S2","kind":"skill","title":"Identify and select the appropriate materials and components for property maintenance tasks, ensuring these are compliant with relevant regulatory requirements and manufacturer's specifications."},{"code":"S3","kind":"skill","title":"Comply with statutory health and safety regulations and requirements."},{"code":"S4","kind":"skill","title":"Comply with risk assessments, and organise the workplace, to safeguard themselves and the property."},{"code":"S5","kind":"skill","title":"Comply with key regulatory and legislative requirements, including building regulations."},{"code":"S6","kind":"skill","title":"Uses safe working practices when carrying out property maintenance tasks including the use of PPE, signage, barriers, access equipment and ensuring work area is prepared and reinstated."},{"code":"S7","kind":"skill","title":"Select, and use work tools and equipment for property maintenance tasks, applying all safeguards, and ensuring the correct functioning of equipment."},{"code":"S8","kind":"skill","title":"Safely isolate and secure electrical or electronic supplies prior to performing property maintenance operations."},{"code":"S9","kind":"skill","title":"Apply and implement routine emergency system checks, testing and routine maintenance, identifying and reporting faults as required."},{"code":"S10","kind":"skill","title":"Perform maintenance and repairs to plumbing systems, including fault identification, safe isolation of supply, replacing components and clearing blockages."},{"code":"S11","kind":"skill","title":"Perform maintenance and repairs to external drainage systems, including clearing blockages and replacing components."},{"code":"S12","kind":"skill","title":"Perform maintenance and repairs to environmental and energy management systems, including fault identification, safe isolation of supply, replacing components."},{"code":"S13","kind":"skill","title":"Use carpentry and joinery skills to perform repairs to windows, doors and glazing units, and their associated fittings."},{"code":"S14","kind":"skill","title":"Perform repairs to plastered surfaces, including surface preparation, fixing and mixing materials and compounds."},{"code":"S15","kind":"skill","title":"Use painting and decorating skills to prepare surfaces for decoration, apply paint using brushes and rollers, and complete sealing activities using gun appliances."},{"code":"S16","kind":"skill","title":"Perform tiling repairs, including setting out, surface preparation and cutting around obstacles."},{"code":"S17","kind":"skill","title":"Perform flooring repairs, including setting out, surface preparation and cutting around obstacles."},{"code":"S18","kind":"skill","title":"Perform planned, responsive or temporary repairs to buildings or their immediate surroundings, attending to minor defects within either masonry, roofing, fencing or railing, groundwork or landscaping."},{"code":"S19","kind":"skill","title":"Select and use technical literature and other sources of information and data to address property maintenance problems."},{"code":"S20","kind":"skill","title":"Record and report information, using digital and written techniques."},{"code":"S21","kind":"skill","title":"Inspect own work, ensuring it is delivered to the given specifications."},{"code":"S22","kind":"skill","title":"Comply with environmental regulations and procedures. Segregate resources for reuse, recycling and disposal."},{"code":"S23","kind":"skill","title":"Use and adapt communication methods for different situations and when, working with colleagues and stakeholders, using industry terminology as appropriate."},{"code":"S24","kind":"skill","title":"Provide customer feedback whilst maintaining customer service."},{"code":"S25","kind":"skill","title":"Escalates issues beyond their level of competence and authority."},{"code":"B1","kind":"behaviour","title":"Prioritise and promote sustainable working practices."},{"code":"B2","kind":"behaviour","title":"Prioritise and promote health and safety."},{"code":"B3","kind":"behaviour","title":"Takes responsibility for completion of own work,"},{"code":"B4","kind":"behaviour","title":"Team focuses to meet goals."},{"code":"B5","kind":"behaviour","title":"Contribute to equality, diverse and inclusive culture."},{"code":"B6","kind":"behaviour","title":"Seek learning and development opportunities."}]}$std$::jsonb, null);
    perform private.publish_standard(v);
  end if;
end $seed$;
